import itertools

# Generate points: all pairs of {0,1,2,3,4,5}
points = list(itertools.combinations(range(6), 2))

# Generate lines: all partitions of {0,1,2,3,4,5} into 3 pairs
lines = []
for p1 in points:
    if p1[0] != 0: continue # Fix first element to avoid duplicates
    rem1 = [x for x in range(6) if x not in p1]
    for p2 in itertools.combinations(rem1, 2):
        p3 = tuple(x for x in rem1 if x not in p2)
        # To avoid duplicate partitions, enforce order
        if p1[0] < p2[0] < p3[0]:
            lines.append((p1, p2, p3))

print(f"Number of points: {len(points)}")
print(f"Number of lines: {len(lines)}")

edges = []
for i, p in enumerate(points):
    for j, l in enumerate(lines):
        if p in l:
            edges.append((i, 15 + j))

print(f"Number of edges: {len(edges)}")

